+  pool.vol = Math.max(0, pool.vol + (WAX_BASE * sim.waxAmt - total) * Math.min(1, dt * 0.6));
+  const Tp = 0.08 + sim.bulb * sim.heat * 1.1;
+  pool.T += (Tp - pool.T) * dt / (Tp > pool.T ? 4.5 : 11);
+  const pTop = poolTop();
+
+  // new blobs swell out of the warm pool
+  sim.spawnIn -= dt * sim.heat;
