+      else if (b.vol >= b.growTo * 0.999) {
+        b.state = 'free'; b.vy = 0.004; b.syv += 0.55; b.cool = 2;
+        if (rng() < 0.45) addBud(b, 0.05 + rng() * 0.1, 1.2 + rng());
+      }
+      constrain(b); continue;
+    }
+    if (b.state === 'bud') {
+      const p = b.parent;
+      if (!p || p.dead || p.state === 'merge') { b.state = 'free'; b.cool = 2; }
+      else {
+        const dv = Math.max(0, Math.min(b.growRate * dt, b.growTo - b.vol, p.vol * 0.5));
+        b.vol += dv; p.vol -= dv; p.r = rOf(p.vol); b.r = rOf(b.vol);
+        const hb = p.r * p.syE * (1 + Math.max(p.tail, 0));
+        b.x = p.x; b.z = p.z; b.y = p.y - hb * (0.45 + 0.4 * b.vol / b.growTo);
+        b.vx = p.vx; b.vy = p.vy; b.vz = p.vz; b.T = p.T - 0.1; b.sy = 1.1;
+        if (b.vol >= b.growTo * 0.999) { b.state = 'free'; b.T = p.T - 0.2; b.vy = p.vy * 0.4; b.cool = 3; p.cool = 3; }
+      }
+      constrain(b); continue;
+    }
+    if (b.state === 'merge') {
+      const tg = b.target === 'pool' ? null : b.target;
+      if (tg && (tg.dead || tg.state === 'merge')) { b.state = 'free'; b.target = null; }
+      else {
+        const k = 1 - Math.exp(-dt * 1.1);
+        const take = Math.min(b.vol, b.vol * k + 1.5e-7 * dt * 60);
+        if (tg) {
+          tg.T = (tg.T * tg.vol + b.T * take) / (tg.vol + take); tg.vol += take; tg.r = rOf(tg.vol);
+          const m = Math.min(1, k * 1.6);
+          b.x += (tg.x - b.x) * m; b.y += (tg.y - b.y) * m; b.z += (tg.z - b.z) * m;
+          b.vx = tg.vx; b.vy = tg.vy; b.vz = tg.vz;
+        } else {
+          pool.T = (pool.T * pool.vol + b.T * take) / (pool.vol + take + 1e-12); pool.vol += take;
+          b.y += (YB + (pTop - YB) * 0.4 - b.y) * Math.min(1, k * 1.2); b.vy = 0;
+        }
+        b.vol -= take; b.r = rOf(b.vol);
+        if (b.vol < 3e-8) b.dead = true;
+        constrain(b); continue;
+      }
+    }
+    // free blob: heat exchange, buoyancy, viscous drag
+    const tau = 7 * Math.max(b.r, 0.006) / 0.02;
+    b.T += (Tenv(b.y) - b.T) * dt / tau;
+    const visc = 1 + 1.8 * Math.max(0, 0.55 - b.T);
+    const c = 0.9 * Math.pow(0.02 / Math.max(b.r, 0.005), 1.2) * visc;
+    const t = sim.t, w = 0.0035;
+    const rad = Math.hypot(b.x, b.z) + 1e-6, conv = 0.004 * (b.T - 0.5);
+    const ax = w * (Math.sin(t * b.f1 + b.p1) + 0.6 * Math.sin(t * b.f2 * 1.7 + b.p2)) - conv * b.x / rad;
+    const az = w * (Math.sin(t * b.f3 + b.p3) + 0.6 * Math.sin(t * b.f1 * 1.3 + b.p4)) - conv * b.z / rad;
+    b.vx += (ax - c * b.vx) * dt; b.vz += (az - c * b.vz) * dt;
+    b.vy += (0.055 * (b.T - 0.5) - c * b.vy) * dt;
+    b.x += b.vx * dt; b.y += b.vy * dt; b.z += b.vz * dt;
+    // stretch + wobble (spring-damper on vertical stretch)
+    const tgtSy = 1 + Math.min(0.45, Math.max(0, b.vy) * 10) + Math.min(0.18, Math.max(0, -b.vy) * 5);
+    b.syv += (-(b.sy - tgtSy) * 5 - b.syv * 1.1 + 0.08 * Math.sin(t * b.f2 * 9 + b.p2)) * dt;
