+    // big rising blobs occasionally pinch off a piece
+    if (b.vol > 6e-5 && b.vy > 0.008 && b.sy > 1.12 && b.cool <= 0 && rng() < dt * 0.05) addBud(b, 0.2 + rng() * 0.25, 1.6 + rng());
+    // cold wax settling on the pool rejoins it
+    const bottom = b.y - b.r * b.syE * (1 + Math.max(b.tail, 0));
+    if (b.T < 0.62 && bottom < pTop + 0.006 && b.vy < 0.003) { b.state = 'merge'; b.target = 'pool'; }
+    constrain(b);
+  }
+
+  // blob/blob contact: merge or press against each other
+  for (let i = 0; i < B.length; i++) {
+    const a = B[i]; if (a.dead || a.state === 'merge') continue;
+    for (let j = i + 1; j < B.length; j++) {
+      const c = B[j]; if (c.dead || c.state === 'merge' || a.state === 'merge') continue;
+      if (a.parent === c || c.parent === a) { if (a.state === 'bud' || c.state === 'bud') continue; }
+      const dx = c.x - a.x, dz = c.z - a.z, dy = (c.y - a.y) / ((a.syE + c.syE) / 2);
+      const d = Math.hypot(dx, dy, dz) + 1e-6, rs = a.r + c.r;
+      if (d >= rs * 0.92) continue;
+      const free = a.state === 'free' && c.state === 'free' && a.cool <= 0 && c.cool <= 0;
