+        const small = a.vol < c.vol ? a : c, big = small === a ? c : a;
+        small.state = 'merge'; small.target = big;
+        big.syv += 0.3 * small.vol / big.vol;
+      } else {
+        const o = (rs * 0.92 - d) / rs, f = 0.09 * o * dt, nx = dx / d, ny = dy / d, nz = dz / d;
+        if (a.state === 'free') { a.vx -= nx * f; a.vy -= ny * f; a.vz -= nz * f; }
+        if (c.state === 'free') { c.vx += nx * f; c.vy += ny * f; c.vz += nz * f; }
+      }
+    }
+  }
+  if (B.some(b => b.dead)) sim.blobs = B.filter(b => !b.dead);
+}
+// warm start: the lamp has already been running for a while
+for (let i = 0; i < 60 * 55; i++) step(1 / 60);
+
+function packUniforms() {
+  let n = 0;
+  for (const b of sim.blobs) {
+    if (n >= MAXB) break;
+    if (b.r < 0.0015) continue;
+    const sy = b.syE;
+    uB[n].set(b.x, b.y, b.z, b.r); uS[n].set(1 / Math.sqrt(sy), sy, b.T, b.tail); n++;
+  }
+  liquidUniforms.uCount.value = n;
+  const pv = sim.pool.vol;
+  liquidUniforms.uPool.value.set(pv / POOL_AREA, sim.pool.T, 0.005 * clamp(sim.pool.T - 0.3, 0, 1) * Math.min(1, pv / 0.0002), 0);
+}
+
+// ---------------------------------------------------------------- colours
+const PRESETS = [
+  { wax: [1.0, 0.16, 0.04], liq: [1.0, 0.80, 0.22] },   // classic red in yellow
+  { wax: [1.0, 0.22, 0.55], liq: [0.36, 0.42, 1.0] },   // pink in violet-blue
+  { wax: [1.0, 0.76, 0.2], liq: [0.13, 0.62, 0.86] },   // amber in lagoon
+  { wax: [0.42, 1.0, 0.1], liq: [0.62, 0.24, 0.95] },   // lime in purple
+  { wax: [0.97, 0.96, 1.0], liq: [0.22, 0.42, 1.0] },   // white in blue
+  { wax: [1.0, 0.4, 0.05], liq: [0.93, 0.95, 0.9] },    // orange in clear
+];
+const curWax = new THREE.Color(...PRESETS[0].wax), curLiq = new THREE.Color(...PRESETS[0].liq);
+const tgtWax = curWax.clone(), tgtLiq = curLiq.clone();
+const lampCol = new THREE.Color();
+
+// ---------------------------------------------------------------- post
+const composerRT = new THREE.WebGLRenderTarget(innerWidth, innerHeight, { type: THREE.HalfFloatType, samples: 4 });
+const composer = new EffectComposer(renderer, composerRT);
+composer.addPass(new RenderPass(scene, camera));
+const bloom = new UnrealBloomPass(new THREE.Vector2(innerWidth, innerHeight), 0.5, 0.65, 0.85);
+composer.addPass(bloom);
+composer.addPass(new OutputPass());
