+    }`,
+});
+composer.addPass(grain);
+
+function applySize() {
+  const w = innerWidth, h = innerHeight;
+  renderer.setPixelRatio(pr); renderer.setSize(w, h);
+  composer.setPixelRatio(pr); composer.setSize(w, h);
+  bgRT.setSize(Math.max(1, Math.floor(w * pr * 0.5)), Math.max(1, Math.floor(h * pr * 0.5)));
+  camera.aspect = w / h; camera.updateProjectionMatrix();
+}
+applySize();
+addEventListener('resize', applySize);
+
+// ---------------------------------------------------------------- env refresh
+let envState = '';
+function refreshEnv(force) {
+  const key = [lampCol.r, lampCol.g, lampCol.b, sim.bulb, roomLevel].map(v => v.toFixed(2)).join();
+  if (!force && key === envState) return;
+  envState = key;
+  const g = sim.bulb;
+  envTable.material.color.copy(lampCol).multiplyScalar(0.35 * g + 0.01);
+  envWall.material.color.copy(lampCol).multiplyScalar(0.12 * g + 0.006);
+  envCeil.material.color.copy(lampCol).multiplyScalar(0.05 * g);
+  envWin.material.color.setRGB(0.16, 0.22, 0.38).multiplyScalar(0.25 + roomLevel * 1.6);
+  envStrip.material.color.setRGB(1.0, 0.95, 0.88).multiplyScalar(0.25 + roomLevel * 1.1);
+  envStrip2.material.color.setRGB(0.9, 0.85, 0.8).multiplyScalar(0.1 + roomLevel * 0.6);
+  cubeCam.update(renderer, envScene);
+  const n = pmrem.fromCubemap(cubeRT.texture);
+  if (envPM) envPM.dispose();
+  envPM = n; scene.environment = n.texture;
+}
+
+// ---------------------------------------------------------------- UI
+let roomLevel = 0.3;
+const $ = id => document.getElementById(id);
+const toSRGB = c => `rgb(${c.map(v => Math.round(Math.pow(clamp(v, 0, 1), 1 / 2.2) * 255)).join(',')})`;
+PRESETS.forEach((p, i) => {
+  const b = document.createElement('button'); b.className = 'sw' + (i === 0 ? ' active' : '');
+  b.style.background = `linear-gradient(135deg, ${toSRGB(p.wax)} 0 48%, ${toSRGB(p.liq)} 52% 100%)`;
+  b.onclick = () => { tgtWax.setRGB(...p.wax); tgtLiq.setRGB(...p.liq); document.querySelectorAll('.sw').forEach(s => s.classList.toggle('active', s === b)); };
+  $('swatches').appendChild(b);
+});
+function bindRange(id, fmt, fn) { const el = $(id), out = $(id + 'O'); const u = () => { fn(+el.value); out.textContent = fmt(+el.value); }; el.addEventListener('input', u); u(); }
+bindRange('heat', v => Math.round(v * 100) + '%', v => sim.heat = v);
+bindRange('flow', v => v.toFixed(1) + '×', v => sim.flow = v);
+bindRange('wax', v => Math.round(v * 100) + '%', v => sim.waxAmt = v);
+bindRange('room', v => Math.round(v * 100) + '%', v => roomLevel = v);
+$('slow').onclick = e => { sim.slow = !sim.slow; e.currentTarget.classList.toggle('on', sim.slow); };
+$('orbit').onclick = e => { controls.autoRotate = !controls.autoRotate; e.currentTarget.classList.toggle('on', controls.autoRotate); };
+$('collapse').onclick = () => { const p = $('panel'); p.classList.toggle('collapsed'); $('collapse').textContent = p.classList.contains('collapsed') ? '+' : '–'; };
+function setPower(on) { sim.power = on; $('power').classList.toggle('on', on); $('pwrTxt').textContent = on ? 'On' : 'Off'; }
+$('power').onclick = () => setPower(!sim.power);
+
+// click the inline cord switch
+const ray = new THREE.Raycaster(), ndc = new THREE.Vector2();
+const swTargets = [swBody, rocker];
+let downAt = null;
+function hitSwitch(e) {
