+  ledMat.color.setRGB(1, 0.42, 0.08).multiplyScalar(sim.power ? 3.0 : 0.02);
+  rocker.rotation.z += ((sim.power ? -0.2 : 0.2) - rocker.rotation.z) * Math.min(1, dt * 18);
+
+  const U = liquidUniforms;
+  U.uTime.value = sim.t; U.uBulb.value = sim.bulb; U.uRoom.value = roomLevel;
+  U.uWax.value.copy(curWax); U.uLiq.value.copy(curLiq);
+
+  if ((envTick += dt) > 0.2) { envTick = 0; refreshEnv(false); }
+
+  controls.update();
+  const cp = camera.position;
+  cp.z = Math.max(cp.z, -0.66); cp.x = clamp(cp.x, -2.15, 2.15); cp.z = Math.min(cp.z, 2.5); cp.y = Math.min(cp.y, 1.85);
