+  grain.uniforms.uTime.value = now / 1000;
+
+  // pass 1: scene without the lamp interior (refraction source); pass 2: full composite
+  renderer.shadowMap.needsUpdate = true;
+  camera.layers.disable(1);
+  renderer.setRenderTarget(bgRT); renderer.render(scene, camera);
+  renderer.setRenderTarget(null);
+  camera.layers.enable(1);
+  composer.render();
