+  // adaptive resolution
+  perfAcc += dt; perfN++; perfT += dt;
+  if (perfT > 1) {
+    const avg = perfAcc / perfN;
+    if (avg > 0.0215 && pr > 0.6) { pr = Math.max(0.6, pr * 0.85); drops++; goodSecs = 0; applySize(); }
+    else if (avg < 0.0175 && pr < maxPR && drops < 3) { if (++goodSecs > 3) { pr = Math.min(maxPR, pr * 1.1); goodSecs = 0; applySize(); } }
