+    statusT = 0;
+    const moving = sim.blobs.some(b => b.state !== 'merge');
+    $('status').textContent = sim.power ? (sim.pool.T < 0.62 && !moving ? 'Warming up' : 'Running') : (moving || sim.bulb > 0.05 ? 'Cooling' : 'Off');
+  }
+}
+refreshEnv(true);
+requestAnimationFrame(animate);
+</script>
+</body>
+</html>

