cd "$PWD" && DEV_BROWSER_ISOLATED=1 timeout 120 dev-browser --browser lavatest <<EOF
const page = await browser.getPage("lava");
const errs = [];
page.on('console', m => { if (m.type()==='error' || m.type()==='warning') errs.push(m.text()); });
